def calculate_factorial(n):
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input must be a non-negative integer.")

    if n == 0:
        return 1
    else:
        result = 1
        for i in range(1, n + 1):
            result *= i
        return result

if __name__ == '__main__':
    # Test cases
    print(f"Factorial of 5: {calculate_factorial(5)}")
    print(f"Factorial of 0: {calculate_factorial(0)}")
    print(f"Factorial of 1: {calculate_factorial(1)}")
    print(f"Factorial of 7: {calculate_factorial(7)}")
    print(f"Factorial of 3: {calculate_factorial(3)}")

    try:
        calculate_factorial(-1)
    except ValueError as e:
        print(f"Error for -1: {e}")

    try:
        calculate_factorial(2.5)
    except ValueError as e:
        print(f"Error for 2.5: {e}")

