    if not isinstance(score, (int, float)):
        raise TypeError("Score must be a number.")
    if not (0 <= score <= 100):
        raise ValueError("Score must be between 0 and 100.")

    if score >= 90:
        return 'A'
    elif score >= 80:
        return 'B'
    elif score >= 70:
        return 'C'
    elif score >= 60:
        return 'D'
    else:
        return 'F'

