def most_frequent_char(text):
    char_counts = {}
    first_occurrence = {}

    for i, char in enumerate(text):
        if char == ' ':
            continue

        char_lower = char.lower()

        if char_lower not in char_counts:
            char_counts[char_lower] = 0
            first_occurrence[char_lower] = i

        char_counts[char_lower] += 1

    if not char_counts:
        return ''

    max_count = -1
    most_frequent = ''
    min_index = float('inf')

    for char, count in char_counts.items():
        if count > max_count:
            max_count = count
            most_frequent = char
            min_index = first_occurrence[char]
        elif count == max_count:
            if first_occurrence[char] < min_index:
                most_frequent = char
                min_index = first_occurrence[char]

    return most_frequent

