def is_valid_parentheses(s: str) -> bool:
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}

    for char in s:
        if char in mapping:
            if not stack:
                return False
            top_element = stack.pop()
            if mapping[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack

