def is_anagram(s1, s2):
    s1_processed = ""
    for char in s1:
        if char.isalpha():
            s1_processed += char.lower()

    s2_processed = ""
    for char in s2:
        if char.isalpha():
            s2_processed += char.lower()

    if len(s1_processed) != len(s2_processed):
        return False

    char_count = {}
    for char in s1_processed:
        char_count[char] = char_count.get(char, 0) + 1

    for char in s2_processed:
        if char not in char_count:
            return False
        char_count[char] -= 1
        if char_count[char] < 0:
            return False

    return True

