def char_frequency(text):
    frequency_map = {}
    lower_text = text.lower()
    for char in lower_text:
        if 'a' <= char <= 'z':
            if char in frequency_map:
                frequency_map[char] += 1
            else:
                frequency_map[char] = 1
        elif char.isdigit():
            if char in frequency_map:
                frequency_map[char] += 1
            else:
                frequency_map[char] = 1
        elif char == ' ':
            if ' ' in frequency_map:
                frequency_map[' '] += 1
            else:
                frequency_map[' '] = 1
        else:
            # Handle other special characters if needed
            if char in frequency_map:
                frequency_map[char] += 1
            else:
                frequency_map[char] = 1
    return frequency_map

