import re

def reverse_words_with_punctuation(sentence):
    if not sentence:
        return ""

    words_and_punctuation = re.findall(r"[\w']+|[^\w\s]", sentence)
    if not words_and_punctuation:
        return sentence

    processed_words = []
    current_word = []

    for item in words_and_punctuation:
        if re.match(r"[\w']+", item):
            if current_word and not re.match(r"[\w']+", current_word[-1]):
                processed_words.append("".join(current_word))
                current_word = []
            current_word.append(item)
        else:
            current_word.append(item)

    if current_word:
