import re

def is_valid_ipv4(ip_address):
    """
    Checks if a given string is a valid IPv4 address.
    """
    if not isinstance(ip_address, str):
        return False

    # Regex for a valid IPv4 address
    # Each octet must be between 0 and 255.
    # ^ and $ ensure the whole string matches.
    ipv4_pattern = re.compile(
        r"^((25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9][0-9]|[0-9])\.){3}"
        r"(25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9][0-9]|[0-9])$"
    )

    if ipv4_pattern.match(ip_address):
        return True
    else:
        # Additional checks can be added here if the regex is too broad,
        # but for this specific pattern, it should be sufficient.
        try:
            octets = ip_address.split('.')
            if len(octets) != 4:
                return False
            for octet_str in octets:
                octet_int = int(octet_str)
                if not (0 <= octet_int <= 255):
                    return False
        except ValueError:
            return False
        except AttributeError:
            return False # This would catch non-string inputs if not already caught

    return False

