def justify_text_simple(words, max_width):
    if not words:
        return ""

    current_line = []
    lines = []
    current_length = 0

    for word in words:
        if not current_line:
            current_line.append(word)
            current_length = len(word)
        elif current_length + 1 + len(word) <= max_width:
            current_line.append(word)
            current_length += 1 + len(word)
        else:
            lines.append(" ".join(current_line))
            current_line = [word]
            current_length = len(word)

    if current_line:
        lines.append(" ".join(current_line))

    result = "\n".join(lines)
    return result

