def find_shortest_word(sentence):
    if not sentence:
        return ""

    import re
    words = re.findall(r'\b\w+\b', sentence.lower())

    if not words:
        return ""

    shortest_word = words[0]
    min_length = len(words[0])

    for word in words:
        current_length = len(word)
        if current_length < min_length:
            min_length = current_length
            shortest_word = word
        elif current_length == min_length:
            # If multiple words have the same shortest length,
            # we keep the first one encountered, so no action needed here.
            pass

    return shortest_word

