def censor_text(text, bad_words):
    censored_text = []
    words = text.split()
    for word in words:
        found_bad = False
        for bad_word in bad_words:
            if bad_word.lower() in word.lower():
                if bad_word.lower() == word.lower():
                    censored_text.append('*' * len(word))
                    found_bad = True
                    break
                else:
                    try:
                        start_index = word.lower().find(bad_word.lower())
                        end_index = start_index + len(bad_word)
                        if start_index != -1:
                            censored_part = '*' * len(bad_word)
                            censored_word = (
                                word[:start_index] +
                                censored_part +
                                word[end_index:]
                            )
                            censored_text.append(censored_word)
                            found_bad = True
                            break
                    except ValueError:
                        pass
        if not found_bad:
            censored_text.append(word)
    return ' '.join(censored_text)

