def geometric_series_sum(a, r, n):
    if not isinstance(a, (int, float)) or \
       not isinstance(r, (int, float)) or \
       not isinstance(n, int):
        raise TypeError("a, r must be numeric, n must be an integer.")

    if n < 0:
        raise ValueError("Number of terms 'n' cannot be negative.")

    if n == 0:
        return 0

    if r == 1:
        sum_val = a * n
    else:
        try:
            sum_val = a * (1 - r**n) / (1 - r)
        except ZeroDivisionError:
            # This case should ideally be caught by r == 1, but as a safeguard
            if r == 1:
                sum_val = a * n
            else:
                raise # Re-raise if some unexpected division by zero occurs

    if isinstance(sum_val, float) and sum_val.is_integer():
        return int(sum_val)
    else:
        return sum_val

