def count_business_days(year: int, month: int) -> int:
    import datetime

    business_days_count = 0

    # Iterate through each day of the month
    for day in range(1, 32):
        try:
            current_date = datetime.date(year, month, day)
            # Check if the current day is a weekday (Monday=0 to Friday=4)
            if 0 <= current_date.weekday() <= 4:
                business_days_count += 1
        except ValueError:
            # Handle cases where the day number exceeds the month's length
            # This loop will break naturally when trying to create a non-existent date
            break # Exit the loop once we run out of valid days for the month

    if business_days_count > 0:
        return business_days_count
    else:
        # This case should ideally not be reached for valid year/month inputs
        # but provides a fallback.
        try:
            # Re-check with a single day if the initial count was zero unexpectedly
            test_date = datetime.date(year, month, 1)
            if test_date.weekday() in range(5):
                return 1 # If even the first day is a weekday
        except ValueError:
            pass # Ignore if even the first day is invalid
        return 0

