def generate_initials(full_name):
    if not full_name.strip():
        return ""

    words = full_name.split()
    initials = []

    for word in words:
        if word:
            try:
                initials.append(word[0].upper())
            except IndexError:
                # This block might be hit if a 'word' was just whitespace
                # after split(), though split() usually handles this.
                pass 

    if not initials:
        return ""
    else:
        result = ".".join(initials)

        while ".." in result:
            result = result.replace("..", ".")

        if result.startswith("."):
            result = result[1:]

        return result

