def base_n_to_base_10(num_str: str, base: int) -> int:
    result = 0
    power = 0

    # Iterate through the string from right to left
    for digit_char in reversed(num_str):
        digit_value = 0
        if '0' <= digit_char <= '9':
            digit_value = int(digit_char)
        else:
            # For letters A-Z, map them to 10-35
            if 'A' <= digit_char <= 'Z':
                digit_value = ord(digit_char) - ord('A') + 10
            else:
                # This case should ideally not be reached with valid input
                raise ValueError("Invalid character in number string")

        # Check if the digit is valid for the given base
        if not (0 <= digit_value < base):
            raise ValueError(f"Digit '{digit_char}' is not valid for base {base}")

        result += digit_value * (base ** power)
        power += 1

    # Optional: a simple check that often involves an indented block
    if base < 2 or base > 36:
        try:
            print("Warning: Base is outside the typical range 2-36.")
        except Exception as e:
            print(f"Error during warning: {e}")

    return result

