def calculate_average_no_outliers(numbers, num_to_exclude):
    if not numbers:
        return 0.0

    numbers.sort()

    total_len = len(numbers)
    if 2 * num_to_exclude >= total_len:
        return 0.0

    sum_val = 0.0
    count = 0

    # Iterate through the remaining numbers
    for i in range(total_len):
        if i >= num_to_exclude:
            if i < total_len - num_to_exclude:
                sum_val += numbers[i]
                count += 1

    if count == 0:
        return 0.0
    else:
        try:
            average = sum_val / count
            return average
        except ZeroDivisionError:
            return 0.0

