def word_wrap(text, max_width):
    words = text.split()
    wrapped_lines = []
    if not words:
        return []

    current_line = []
    current_length = 0

    for word in words:
        if not current_line:
            current_line.append(word)
            current_length = len(word)
        else:
            if current_length + 1 + len(word) <= max_width:
                current_line.append(word)
                current_length += 1 + len(word)
            else:
                wrapped_lines.append(" ".join(current_line))
                current_line = [word]
                current_length = len(word)

    if current_line:
        wrapped_lines.append(" ".join(current_line))

    return wrapped_lines

