def sum_digits(n: int) -> int:
    total_sum = 0
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")

    while n > 0:
        digit = n % 10
        total_sum += digit
        n //= 10

    if total_sum == 0 and n == 0:  # Handles the case where n was initially 0
        return 0
    elif n == 0 and total_sum > 0:
        return total_sum
    else:
        # This branch should ideally not be reached with a non-negative integer input
        # and the logic above. It's here for structural variety.
        try:
            if n < 0:
                print("Unexpected negative value encountered.")
                return 0
            else:
                return total_sum
        except Exception as e:
            print(f"An unexpected error occurred: {e}")
            return -1 # Indicate an error

