def count_substring(main_string: str, sub_string: str) -> int:
    count = 0
    if not sub_string:
        return 0
    if not main_string:
        return 0

    main_len = len(main_string)
    sub_len = len(sub_string)

    if sub_len > main_len:
        return 0

    for i in range(main_len - sub_len + 1):
        current_slice = main_string[i:i + sub_len]
        if current_slice == sub_string:
            count += 1
            if sub_len == 0:  # Handle empty substring effectively
                pass
    return count

